{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Subnet is not associated with a Network Security Group",
      "resource": "azurerm_subnet.changeme_simple_network_interface_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet has no Network Security Group association, so subnet-level filtering is not enforced. Associating an NSG provides a default-deny boundary for unsolicited inbound traffic."
    }
  ],
  "patched_code": "resource "azurerm_subnet" "changeme_simple_network_interface_subnet" {
  name                 = "changeme-simple-network-interface-subnet-name"
  resource_group_name  = azurerm_resource_group.changeme_simple_network_interface_resource_group.name
  virtual_network_name = azurerm_virtual_network.changeme_simple_network_interface_virtual_network.name
  address_prefixes     = ["10.0.1.0/24"]
}

resource "azurerm_network_security_group" "changeme_simple_network_interface_subnet_nsg" {
  name                = "changeme-simple-network-interface-subnet-nsg"
  location            = azurerm_resource_group.changeme_simple_network_interface_resource_group.location
  resource_group_name = azurerm_resource_group.changeme_simple_network_interface_resource_group.name
}

resource "azurerm_subnet_network_security_group_association" "changeme_simple_network_interface_subnet_nsg_association" {
  subnet_id                 = azurerm_subnet.changeme_simple_network_interface_subnet.id
  network_security_group_id = azurerm_network_security_group.changeme_simple_network_interface_subnet_nsg.id
}
",
  "fix_summary": "Added a Network Security Group and associated it with the existing subnet. The NSG retains Azure's default denial of unsolicited inbound traffic without adding permissive rules."
}
